import React, { useState } from "react";
import { Calendar } from "primereact/calendar";
import { format } from "date-fns";

export default function InlineDemo() {
  const [date, setDate] = useState(null);

  // Example appointment data (Replace this with your actual data from API)
  const appointments = [
    { date: "2025-03-19" },
    { date: "2025-03-19" },
    { date: "2025-03-21" },
    { date: "2025-03-25" },
  ];

  // Function to count appointments per date
  const countAppointments = (day) => {
    const formattedDay = format(new Date(day), "yyyy-MM-dd");
    return appointments.filter((appt) => appt.date === formattedDay).length;
  };

  return (
    <div className="card flex justify-content-center">
      <Calendar
        value={date}
        onChange={(e) => setDate(e.value)}
        inline
        showWeek
        dayTemplate={(day) => {
          const count = countAppointments(day);
          return (
            <div className="relative text-center">
              <span>{day.getDate()}</span>
              {count > 0 && (
                <span
                  className="absolute bottom-0 left-1/2 transform -translate-x-1/2 bg-red-500 text-white text-xs font-bold rounded-full px-2 py-1"
                >
                  {count}
                </span>
              )}
            </div>
          );
        }}
      />
    </div>
  );
}
